/**
 * One sidebar per partner, so a partner's pages only show that partner's navigation:
 * its docs (autogenerated from the folder) plus a link to each contract version.
 */
import type { SidebarsConfig } from '@docusaurus/plugin-content-docs';
import { loadPartners } from './scripts/lib/partners.mjs';

const { partners } = loadPartners(__dirname);

const sidebars: SidebarsConfig = Object.fromEntries(
  partners.map((p) => [
    `partner-${p.id}`,
    [
      { type: 'autogenerated', dirName: p.id },
      {
        type: 'category',
        label: 'API contracts',
        collapsed: false,
        items: p.versions.map((v) => ({
          type: 'link' as const,
          label: `${v.version}${v.status !== 'current' ? ` (${v.status})` : ''}`,
          href: `/partners/${p.id}/${v.version}`,
        })),
      },
      { type: 'link', label: '← All partners', href: '/partners' },
    ],
  ]),
);

export default sidebars;
